import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  user: {},
  isLoading: false,
  isSuccess: false,
  isError: false,
};

// ✅ Register User (Student OR Company)
export const registerUser = createAsyncThunk(
  "users/studentregister",
  async (formData, thunkAPI) => {
    try {
      const response = await axios.post(
        "http://localhost:3001/studentregister",
        formData
      );

      return response.data;
    } catch (error) {
      return thunkAPI.rejectWithValue(
        error.response?.data?.msg || "Server error"
      );
    }
  }
);

// ✅ Login User
export const loginUser = createAsyncThunk(
  "users/studentregister",
  async (loginData, thunkAPI) => {
    try {
      const response = await axios.post(
        "http://localhost:3001/studentlogin",
        loginData
      );

      // Save user in localStorage
      localStorage.setItem("userData", JSON.stringify(response.data.user));

      return response.data.user;
    } catch (error) {
      return thunkAPI.rejectWithValue(
        error.response?.data?.msg || "Wrong email or password"
      );
    }
  }
);

export const userSlice = createSlice({
  name: "users",
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder

      // ✅ register user
      .addCase(registerUser.pending, (state) => {
        state.isLoading = true;
        state.isError = false;
        state.isSuccess = false;
      })
      .addCase(registerUser.fulfilled, (state) => {
        state.isLoading = false;
        state.isSuccess = true;
      })
      .addCase(registerUser.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      })

      // ✅ login user
      .addCase(loginUser.pending, (state) => {
        state.isLoading = true;
        state.isError = false;
      })
      .addCase(loginUser.fulfilled, (state, action) => {
        state.isLoading = false;
        state.user = action.payload;
        state.isSuccess = true;
      })
      .addCase(loginUser.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      });
  },
});

export default userSlice.reducer;
